-- 040: эксперты — свои реплики на каждую улику (168 запасных реакций) и вещдоки в fallback_lines
begin;
update characters set name = 'Гульнара Сеитова', role = 'Криминалист ЭКО', intro_text = 'Гульнара Сеитова, эксперт-криминалист ЭКО ГУВД. Свитер под белым халатом, волосы в узел.
Сеитова не поднимает головы от кальки.
— Что смотреть? Давайте конкретно.', fixed_questions = '[{"q": "Что вы можете сделать по этому делу?", "a": "— Осмотр. Трасология, следы рук. Сравнение предметов. Купюры по номерам тоже, если будет с чем сравнивать. Если картотеку не поднимать — результат в тот же день. Картотека у Абишева."}, {"q": "Как по-вашему, это несчастный случай?", "a": "— Я говорю по предмету. Привезёте предмет — скажу, что на нём есть. А случай это или нет, решает следствие."}]'::jsonb, reactions = '{"b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким слоем снега. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу.", "46e78eb0-d057-5e5d-8a00-81457f8f3d20": "Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали все шесть.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "Сеитова кладёт стопку протоколов рядом с листами ксерокопий.\n— Доллары из мешка с рисом. Пересчитала при понятых, номера переписала, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Лишних нет. Чужих нет. Банковские резинки описаны. Рис описан отдельно.", "4f67be3f-f5f7-5ab5-bb69-611053df3042": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Арык у ворот сфотографировала. Где лежал — в протоколе.", "60950128-af31-513e-b8de-bb87b02332cc": "Сеитова раскладывает кальки.\n— Обувь. Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий. Изъяла у него всё, что есть. Импортные туфли — подошва гладкая, кожаная. Зимние ботинки — протектор другой, пореза нет. Жумабаева: тридцать седьмой. Мужские следы у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что принесли, нет.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "Сеитова возвращается со стоянки Медеуского РОВД. На рукаве халата рыжая полоса глины.\n— Раз не угар, смотреть надо машину. Посмотрела. В колёсных арках жёлтая глина. Плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора. В Горном Гиганте, например. На Кок-Тобе к даче асфальт и щебень, там такую не наберёшь.\nРуль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — не моя графа.", "a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне."}'::jsonb, reaction_rules = '[{"id": "R03", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким слоем снега. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу.", "grants": ["60950128-af31-513e-b8de-bb87b02332cc"]}, {"id": "R24", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне.", "grants": ["d91852b9-daca-5340-80c9-a13cffe680cc"]}, {"id": "R27", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": ["60950128-af31-513e-b8de-bb87b02332cc"], "text": "Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали все шесть.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне.", "grants": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d"]}, {"id": "R28", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "Сеитова кладёт стопку протоколов рядом с листами ксерокопий.\n— Доллары из мешка с рисом. Пересчитала при понятых, номера переписала, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Лишних нет. Чужих нет. Банковские резинки описаны. Рис описан отдельно.", "grants": ["107fcb2c-e909-5f81-bba4-d218265227c5"]}, {"id": "R30", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["5cdb3307-fe10-53c5-a365-6998256b7d7a", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R47", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Арык у ворот сфотографировала. Где лежал — в протоколе.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R50", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Сеитова раскладывает кальки.\n— Обувь. Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий. Изъяла у него всё, что есть. Импортные туфли — подошва гладкая, кожаная. Зимние ботинки — протектор другой, пореза нет. Жумабаева: тридцать седьмой. Мужские следы у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что принесли, нет.", "grants": ["7a9bdd9a-4323-5342-a3bd-24301a6d6e88"]}, {"id": "R59", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042", "27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R60", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}, {"id": "R64", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Сеитова возвращается со стоянки Медеуского РОВД. На рукаве халата рыжая полоса глины.\n— Раз не угар, смотреть надо машину. Посмотрела. В колёсных арках жёлтая глина. Плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора. В Горном Гиганте, например. На Кок-Тобе к даче асфальт и щебень, там такую не наберёшь.\nРуль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — не моя графа.", "grants": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}, {"id": "R67", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне.", "grants": []}, {"id": "R136", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "— По протоколу угар. Машину РОВД не осматривал, только описал. Пока Кан не скажет, что не угар, смотреть её мне не на что.", "grants": [], "fallback": true}, {"id": "R137", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Сеитова читает акт до конца.\n— В машину посадили мёртвым. Значит, машину смотреть надо. Где она, на стоянке РОВД? Дайте их протокол.", "grants": [], "fallback": true}, {"id": "R138", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "— Следы с люка и лампы снимала я. Сравнение по картотеке Абишева. Второй набор в картотеке не значится. Дадите дактокарту человека — сравню.", "grants": [], "fallback": true}, {"id": "R139", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Задержанного откатаем. Пальцы, обувь. Сравнивать буду с подвалом. Материалы подвала мне на стол.", "grants": [], "fallback": true}, {"id": "R140", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Ксерокопии купюр — это материал. Несите копии. И то, с чем сравнивать: купюры. Без второго сравнивать нечего.", "grants": [], "fallback": true}, {"id": "R141", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— Сорок тысяч ушли. Номера кто-то переписывал? Если нет — сравнивать не с чем. Появятся купюры — ко мне.", "grants": [], "fallback": true}, {"id": "R142", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— По свежему снегу в ночь на воскресенье. С тех пор оттепель. Там каша, колею уже не снять. Не моя графа — только время.", "grants": [], "fallback": true}, {"id": "R143", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Женские тридцать седьмого, под коркой слякоти. Дневные. Я так и писала. С её словами не спорят.", "grants": [], "fallback": true}, {"id": "R144", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— Разбитую фару сравнивать не с чем. Нет машины — нет экспертизы. Номер найдёте — посмотрю фару.", "grants": [], "fallback": true}, {"id": "R145", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— Покупателя по следам не установишь. Фамилию назовёт — возьму пальцы, сравню с лампой.", "grants": [], "fallback": true}, {"id": "R146", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"], "text": "— Горный Гигант. Глина в арках как раз такая. Только грунт со двора мне никто не привёз. Сначала там побывайте.", "grants": [], "fallback": true}, {"id": "R147", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Сеитова уже застёгивает сумку.\n— Санкция есть — еду с вами. Всё, что изымем, сразу ко мне. Обувь отдельно, деньги отдельно.", "grants": [], "fallback": true}, {"id": "R148", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"], "text": "— На машине Сартакова, в перчатках. Глина и чистый руль с этим сходятся. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R211", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "— Моё заключение. Будет обувь — сравню с калькой.", "grants": [], "fallback": true}, {"id": "R234", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["c2c5ba62-e24e-523f-93bc-d8909b28e717", "3772cdd6-1fe9-52d0-a268-3f82441220c7"], "text": "— Горный Гигант. Глина в арках как раз такая. Грунт со двора Шмидтов — под навесом — возьму, сравню. Двор вы уже видели.", "grants": [], "supersedes": ["R146"], "fallback": true}, {"id": "R243", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "— Копии у меня. Купюры будут — сравню.", "grants": [], "supersedes": ["R141"], "fallback": true}, {"id": "R244", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"], "text": "— Второй набор — Бекенов. Справка у вас.", "grants": [], "supersedes": ["R138"], "fallback": true}, {"id": "R245", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"], "text": "— Второй набор — Бекенов. Справка у вас.", "grants": [], "supersedes": ["R139"], "fallback": true}, {"id": "R294", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Сеитова читает журнал приёма. Видит прочерк в графе «исследование».\n— Прочерк. В графе прочерк.\n(возвращает)\nЭто к Юрию Николаевичу. Тело не моё.", "grants": [], "fallback": true}, {"id": "R295", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": [], "text": "Сеитова смотрит фототаблицу РОВД.\n— Снято без масштабной линейки. Расстояния не определить. Ракурс один.\n(откладывает)\nКак доказательство — слабо. Борозды надо было снимать сверху.", "grants": [], "fallback": true}, {"id": "R296", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "— Определитель номера. Пластмасса, китайская сборка.\n(не берёт)\nОтпечатки с кнопок снимать бессмысленно: пользовалась вся семья. Номера — к Абишеву.", "grants": [], "fallback": true}, {"id": "R297", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "Сеитова держит конверт за угол пинцетом.\n— Конверт почтовый, без марки. Пять купюр по сто. Бумага рыхлая, отпечатков с неё не сниму.\n(кладёт)\nПока это просто деньги.", "grants": [], "fallback": true}, {"id": "R298", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "— Рабочие заметки. От руки.\n(возвращает, не дочитав)\nНе моя графа. Рука на бумаге — не рука. Повязку я не снимаю, это к судмедэксперту.", "grants": [], "fallback": true}, {"id": "R299", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "Сеитова пролистывает журнал КПП.\n— Записи шариковой ручкой. Почерк один, ровный, дневной дежурный. Исправлений нет.\n(закрывает)\nПо моей части — документ без подчисток. Остальное не моя графа.", "grants": [], "fallback": true}, {"id": "R300", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": [], "text": "— Ксерокопии. Качество приличное, номера и серии читаются без лупы.\n(выравнивает пачку)\nСами по себе — бумага. Сверять пока не с чем.", "grants": [], "fallback": true}, {"id": "R301", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": [], "text": "— Пейджер. Корпус потёртый.\n(переворачивает)\nПамять стёрта — восстанавливать не умею, это не криминалистика. Номер на наклейке — к Абишеву.", "grants": [], "fallback": true}, {"id": "R302", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Сеитова узнаёт свой протокол.\n— Мой. Следы пальцев с крышки люка и с лампы изъяты, наклеены, описаны.\n(постукивает ногтем по строке)\nСравнение с картотекой — Абишев. Моё дело — чтобы было что сравнивать.", "grants": [], "fallback": true}, {"id": "R303", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "Сеитова раскатывает шарф на столе. Проводит пальцем.\n— Шерсть, кашемир. Бирка импортная.\n(пауза, чуть тише)\nДорогая вещь. Я себе такую не куплю.\n(сворачивает)\nПятна — сырость. По моей части всё.", "grants": [], "fallback": true}, {"id": "R304", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "— Телефонный аппарат. На трубке пыли нет, на полке — слой.\n(записывает)\nЭто я и в протокол внесу. Номер — к Абишеву. По моей части всё.", "grants": [], "fallback": true}, {"id": "R305", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "Сеитова раскладывает опись.\n— Куртка синяя, полосы белые. Шапка-ушанка. Ботинки сорок пятого. Тридцать купюр.\n(сверяет)\nОпись верная. Сравнивать с чем — скажете.", "grants": [], "fallback": true}, {"id": "R306", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": [], "text": "— Журнал вахты. Записи в одну руку, без исправлений.\n(возвращает)\nПодделки не вижу. Остальное — показания. Не моя графа.", "grants": [], "fallback": true}, {"id": "R307", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Ботинки изъяты?\n(смотрит протокол обыска)\nПредмет мне сюда, в пакете, опечатанный. С бумаги подошву не сравнивают.", "grants": [], "fallback": true}, {"id": "R308", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "Сеитова смотрит расписку против света.\n— Бланк типографский. Печать смазана, текст печати не читается. Сумма исправлена дважды, той же пастой.\n(откладывает)\nПочерковед нужен, не я. Кто кому должен — не моя графа.", "grants": [], "fallback": true}, {"id": "R309", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Мешок риса, пакет, деньги, бумаги.\n(надевает перчатки)\nПересчитаю при понятых, номера перепишу. Сравнивать пока не с чем.", "grants": [], "fallback": true}, {"id": "R310", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "— Справка по пейджеру. Подпись моя на первой половине.\n(показывает)\nПросушила, элемент питания заменила. Вторая половина — Абишев. Повторять не буду. Там всё.", "grants": [], "fallback": true}, {"id": "R311", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "Сеитова читает объяснение водителя.\n— «Месяц тебе, или сядешь».\n(отодвигает)\nСлова. Слова не измеряются. Не моя графа.", "grants": [], "fallback": true}, {"id": "R312", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— Со слов. «Помирились», «свечка».\n(не поднимает головы)\nСо слов не работаю. Предмет будет — скажу.", "grants": [], "fallback": true}, {"id": "R313", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "— Ссора в октябре.\n(возвращает)\nНе моя графа. Я про то, что осталось на месте, а не про то, что говорили в кабинете.", "grants": [], "fallback": true}, {"id": "R314", "on": "9eedb06d-09c9-5fa6-b91f-46d7753f78b4", "requires": [], "text": "— Свет отключали с девятнадцати до двух.\n(записывает в блокнот)\nДля осмотра в темноте нужен фонарь. Для экспертизы — ничего. Справка не моя.", "grants": [], "fallback": true}, {"id": "R315", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": [], "text": "— «Орбита». Свет был.\n(пожимает плечами)\nЭто учёт электросетей. Не моя графа. Абишев проверял — значит, проверено.", "grants": [], "fallback": true}, {"id": "R316", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "— Журнал оператора. Четыре слова и буква.\n(отодвигает)\nБуква — не подпись. Почерка нет, оператор печатал. Не моя графа.", "grants": [], "fallback": true}, {"id": "R317", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "Сеитова пробегает глазами признание Нуртазина.\n— Признание.\n(возвращает)\nПризнание — не доказательство, пока нет предмета. Моих предметов тут нет.", "grants": [], "fallback": true}, {"id": "R318", "on": "3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0", "requires": [], "text": "— Консультация Бейсенова.\n(читает одну строку, откладывает)\nЭто теория. Я по теории не работаю. Принесёте вещь — скажу размер.", "grants": [], "fallback": true}, {"id": "R319", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": [], "text": "Сеитова узнаёт протокол сравнения.\n— Мой протокол. Тридцать купюр, все в копиях.\n(возвращает)\nПодпись моя. Повторять не буду.", "grants": [], "fallback": true}, {"id": "R320", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Очная ставка.\n(читает, не меняясь в лице)\nПоказания. Не моя графа. Мои заключения от них не меняются.", "grants": [], "fallback": true}, {"id": "R321", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": [], "text": "— Моё заключение. Шесть точек из шести.\n(кладёт ладонь на лист)\nВ суде повторю слово в слово. Здесь — не буду.", "grants": [], "fallback": true}, {"id": "R322", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": [], "text": "— Мой протокол сравнения. Каждая купюра из мешка есть в копиях.\n(закрывает папку)\nЛишних нет. Повторять не буду.", "grants": [], "fallback": true}, {"id": "R323", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Сеитова читает заключение Кана.\n— Юрий Николаевич смотрел.\n(возвращает)\nЕсли он пишет «ногти» — значит, ногти. Оспаривать не буду. Не моё.", "grants": [], "fallback": true}, {"id": "R324", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "— Моё сравнение. Пять купюр из конверта, все пять в копиях.\n(без выражения)\nУстановлено. Подпись моя.", "grants": [], "fallback": true}, {"id": "R325", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "— Группы крови. Справка Юрия Николаевича.\n(сверяет со своими записями)\nС моими материалами не расходится. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R326", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "— Моё заключение по обуви фигурантов.\n(постукивает по строкам)\nКаждая пара проверена. Ни одна не подошла. Повторять не буду.", "grants": [], "fallback": true}, {"id": "R327", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "— Справка ГАИ.\n(откладывает)\nЦвет машины — не след. Краску с места я не изымала. Не моя графа.", "grants": [], "fallback": true}, {"id": "R328", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Адресное бюро. Родство.\n(не читает дальше первой строки)\nРодство не измеряется. Не моя графа.", "grants": [], "fallback": true}, {"id": "R329", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Сводная. Первая строка моя: второй набор пальцев с люка.\n(показывает пальцем)\nУстановлено. Остальное — Юрий Николаевич и Абишев.", "grants": [], "fallback": true}, {"id": "R330", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Объяснение соседки.\n(возвращает)\nСоседки видят много. Измерить нельзя ничего. Не моя графа.", "grants": [], "fallback": true}, {"id": "R331", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "Сеитова смотрит на таблицу дат.\n— Таблица. Даты из показаний.\n(пожимает плечами)\nПоказания — не моя графа. Даты экспертиз в ней верные.", "grants": [], "fallback": true}, {"id": "R332", "on": "3772cdd6-1fe9-52d0-a268-3f82441220c7", "requires": [], "text": "Сеитова читает справку об осмотре машины.\n— Глина в арках, жёлтая. Руль чистый.\n(записывает)\nОбразец глины не изъят. Изъяли бы — сказала бы, откуда. Теперь поздно.", "grants": [], "fallback": true}, {"id": "R333", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "— Дополнительный допрос.\n(отодвигает)\nПоказания. Царапины по словам свидетеля — не царапины. Нужно освидетельствование. Это к Юрию Николаевичу.", "grants": [], "fallback": true}]'::jsonb, fallback_lines = '{"testimony": ["— Со слов не работаю. Нужен предмет: обувь, купюра, след.", "— Не моя графа. Принесёте вещь — скажу размер."], "expertise": ["— Заключение не моё. Оспаривать не буду. Добавить нечего.", "— Это не по моему профилю. Вещь будет — посмотрю."], "document": ["— Справка не моя. По моей части в ней ничего.", "— Бумага. Материала для экспертизы в ней нет."], "own_expertise": "— Моё заключение. Новых предметов нет — добавить нечего.", "thing": ["— Предмет вижу. Задачу не вижу. Что установить?", "— Пригодных следов нет. Размер, материал — пожалуйста. Остальное не моя графа."]}'::jsonb where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set name = 'Ринат Абишев', role = 'Оператор ИВЦ ГУВД', intro_text = 'Ринат Абишев, оператор ИВЦ ГУВД. Картотечные ящики до потолка. На столе кружка остывшего чая.
— С запросом? Давайте. Только сразу скажу: всё по бумаге и не раньше чем через день. Ну, так у нас.', fixed_questions = '[{"q": "Что вы можете проверить?", "a": "— Ну, судимости. Дактокарты. Адресное бюро, машины через ГАИ. Могу написать запрос на АТС, в пейджинговую, в электросети. Всё письменно, с подписью, и всё через день. Компьютер у нас, вот, один. И тот в бухгалтерии."}, {"q": "Что ещё имеет смысл проверить?", "a": "— Если похищение и был дом, где держали… Ну, тогда проверяйте всех, кто в тот вечер чем-то подтверждает, где был. Свет, телефон, смены. Свет я могу поднять отдельно по каждому району, хоть по улице. Скажите только какую. Электросети, они всё пишут: где отключали, где нет.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931", "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"q": "Как убийца ночью спустился с Кок-Тобе, если машину оставил в гараже?", "a": "— Пешком. А внизу частника остановил. Ну а как ещё. Частника вы не найдёте: они нигде не записываются. В субботу вечером по городу каждый второй с машиной подрабатывает. Это не след. Ищите то, что где-то записано.", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}]'::jsonb, reactions = '{"1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Позвонил в пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: не перезвонил ни разу.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы уж вы сами.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, РОВД проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. Потом сам съездил: без печати бумагу не отдают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут РОВД прав.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "Абишев выслушивает. Стул под ним скрипит.\n— Пальцы на керосиновой лампе, в доме в Горном Гиганте. А сам он, говорит, сидел при свечке в «Орбите». Понял. «Орбиту» никто не запрашивал. Пишу отдельно. Сразу за пятницу и за субботу, чтобы второй раз не ездить.\nЧерез день на столе бумага с печатью.\n— Вот. Ни в пятницу, ни в субботу в «Орбите» не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка. Выводы — ваши.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, пятнадцать тридцать. Хорошо, что у неё АОН на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот бы уже вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонили из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Номер, который ваш финансист с АОН запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в ФРГ на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Судим в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению.", "be5c249c-d25f-5239-865f-5aef2088bc61": "Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет.", "f725c4c5-f254-5c01-b718-3531a957102a": "— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» никто не проверял. Сейчас. Заодно и пятницу спрошу, чтобы два раза не звонить.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Знать вы это можете уже сегодня.", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf": "Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз все бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. «Волга» с одной фарой у ворот базы — четырнадцатое, четверг. «Месяц тебе, или сядешь» — шестнадцатое, суббота. Похищение — двадцать первое.\nТычет ручкой в первые две строки.\n— Вот эти две — раньше крика в кабинете. Больше тут ничего не написано. Остальное — ваше."}'::jsonb, reaction_rules = '[{"id": "R02", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Позвонил в пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: не перезвонил ни разу.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы уж вы сами.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R10", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, РОВД проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. Потом сам съездил: без печати бумагу не отдают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут РОВД прав.", "grants": ["9eedb06d-09c9-5fa6-b91f-46d7753f78b4"]}, {"id": "R11", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Абишев выслушивает. Стул под ним скрипит.\n— Пальцы на керосиновой лампе, в доме в Горном Гиганте. А сам он, говорит, сидел при свечке в «Орбите». Понял. «Орбиту» никто не запрашивал. Пишу отдельно. Сразу за пятницу и за субботу, чтобы второй раз не ездить.\nЧерез день на столе бумага с печатью.\n— Вот. Ни в пятницу, ни в субботу в «Орбите» не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка. Выводы — ваши.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R12", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, пятнадцать тридцать. Хорошо, что у неё АОН на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот бы уже вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонили из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R13", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Номер, который ваш финансист с АОН запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в ФРГ на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R17", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Судим в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"]}, {"id": "R20", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"]}, {"id": "R38", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Мамаджанов? Он у нас есть. Судим в девяносто четвёртом, таможня, дактокарта с тех пор лежит. — Абишев тянет с полки ящик картотеки. — Сравнивал вручную, полночи. Пальцы с крышки люка и с керосиновой лампы — его, Гульнара подтвердит. Второй набор с люка в картотеке не значится: человек несудимый. И раз уж я в его деле сидел: медкарта колонии, группа крови вторая. Это так, к сведению. В медицине я не понимаю.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "supersedes": ["R17"]}, {"id": "R48", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» никто не проверял. Сейчас. Заодно и пятницу спрошу, чтобы два раза не звонить.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Знать вы это можете уже сегодня.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R51", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Абишев тянется за сигаретами.\n— «Волга» с одной фарой? По вашему кругу запросил ИЦ и ГАИ. Мамаджанов Ф. — ГАЗ-24, «Волга», белая. Что у неё с фарами, ГАИ не пишет, в карточке такого нет. Ахметов — ВАЗ-2109, белая. Попросил гаишников глянуть у офиса: фары целы, обе. Жумабаева — «Таврия», красная. Нуртазин — личной машины нет, ездит на служебном «уазике» агентства. Белых, значит, две. Дальше смотрите сами.", "grants": ["d8f33493-fc81-5e50-af40-37d9500040b6"]}, {"id": "R57", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["0a295d5f-e115-5c89-a26a-5992761304a0", "c4c95f03-86b0-5820-b9f4-736453e2dbef"], "text": "Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз все бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. «Волга» с одной фарой у ворот базы — четырнадцатое, четверг. «Месяц тебе, или сядешь» — шестнадцатое, суббота. Похищение — двадцать первое.\nТычет ручкой в первые две строки.\n— Вот эти две — раньше крика в кабинете. Больше тут ничего не написано. Остальное — ваше.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}, {"id": "R58", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "c2c5ba62-e24e-523f-93bc-d8909b28e717"], "text": "Абишев откладывает пейджер охранника.\n— Номер на наклейке есть. Позвонил в пейджинговую. Журнал за двадцать первое: шестнадцать тридцать, абонент Нуртазин, текст «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто подписался «Ф.», в журнале не пишут. Это справка, не обвинение.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"], "supersedes": ["R20"]}, {"id": "R61", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Высокий молодой парень вышел из «Волги» вместе с Мамаджановым? Значит, смотрим, кто у Мамаджанова в городе из молодых. — Абишев снимает с полки учётное дело девяносто четвёртого года, листает анкету. — Графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Дальше адресное бюро. По городу прописан один Бекенов оттуда. Олжас, двадцать два года. Временная прописка: общежитие у Зелёного базара, комната четыреста двенадцать. Племянник, выходит. Это фамилия и адрес. Остальное не ко мне.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"id": "R62", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "— Курьер на остановке: высокий, молодой, куртка, ушанка. И пальцы Мамаджанова в том подвале. Ну, значит, смотрим, кто у Мамаджанова в городе из молодых. — Абишев снова достаёт учётное дело девяносто четвёртого года. — Анкета, графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Адресное бюро: в городе временно прописан Бекенов Олжас, двадцать два года, оттуда же. Общежитие у Зелёного базара, комната четыреста двенадцать. Вот справка.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"id": "R149", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "Абишев вздыхает.\n— Белая двадцать четвёртая, одна фара. Номера нет. Белых «Волг» в ГАИ по городу — тысячи. Фару в учёт не пишут. Будут фамилии — проверю, на ком какая машина.", "grants": [], "fallback": true}, {"id": "R150", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Крик в кабинете. Ни номера, ни адреса, ни даты для журнала. Запрос делать не по чему. Это справка, не обвинение, — а тут даже справки нет.", "grants": [], "fallback": true}, {"id": "R151", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Журнал дежурств — больничный. Там уже всё подтверждено, с подписью. Мне по моим учётам проверять нечего.", "grants": [], "fallback": true}, {"id": "R152", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— Номер остался в определителе? Тогда мне нужен сам номер. Цифры с аппарата — и я его по адресному бюро подниму. Со слов цифры не возьмёшь.", "grants": [], "fallback": true}, {"id": "R153", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— «Орбиту» в электросетях запросить можно. Только с чего? Человек пришёл с соболезнованием, сказал, что сидел дома. Он у вас не фигурант. Дайте основание — запрошу.", "grants": [], "fallback": true}, {"id": "R154", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "— Судимость девяносто четвёртого — в картотеке есть, подтвердится. Только что судим, вы и так знаете. Под что запрос? Нужен вопрос: телефон, адрес, машина.", "grants": [], "fallback": true}, {"id": "R155", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "— Чайхана, пейджер, даты. Даты я сложить могу. Только таблица из одних его слов — не таблица. Других показаний с датами мало.", "grants": [], "fallback": true}, {"id": "R156", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— С таксофона звонили — по АТС такой звонок не поднимешь. Таксофон он и есть таксофон. По этим словам запрос делать не по чему.", "grants": [], "fallback": true}, {"id": "R157", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Это очная ставка, не справка. В моих учётах нет ни кашля, ни «Беломора».", "grants": [], "fallback": true}, {"id": "R158", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "— Частник, номер не помнит. Без номера машину не найти.", "grants": [], "fallback": true}, {"id": "R159", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Чья «девятка», и так ясно. Где она ночью стояла, ГАИ не пишет. Проверять тут по учётам нечего.", "grants": [], "fallback": true}, {"id": "R160", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— Покупатель без фамилии. Запрос делать не по чему. Назовёт фамилию — подниму по адресному бюро за час. Вывод сами.", "grants": [], "fallback": true}, {"id": "R161", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "— Кто ему руку поцарапал, в учётах не найдёшь. Руку пусть Кан смотрит.", "grants": [], "fallback": true}, {"id": "R162", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "— Группа — это медицина, к Кану. Вот если человек у нас в учёте — тогда и медкарту найду. Дайте фамилию.", "grants": [], "fallback": true}, {"id": "R163", "on": "3772cdd6-1fe9-52d0-a268-3f82441220c7", "requires": [], "text": "— Горный Гигант — это сотни дворов, улицы без названий. Без улицы и дома запрос не сделать.", "grants": [], "fallback": true}, {"id": "R164", "on": "3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0", "requires": [], "text": "— Круг лиц — это не запрос. Фамилии будут — проверю по всем учётам. Вывод сами.", "grants": [], "fallback": true}, {"id": "R174", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Четвёртый пункт мой: данные ГАИ по машинам. Остальное — Сеитова и Кан.\n(постукивает ручкой по строчке)\nМоё там всё верно. Вывод сами.", "grants": [], "fallback": true}, {"id": "R235", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "64b699fc-69d6-5bc3-ab81-b5a48df561bd"], "text": "— «Орбиту» я уже проверял. Свет там был и в пятницу, и в субботу. Справка у вас.", "grants": [], "supersedes": ["R48"]}, {"id": "R236", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4", "64b699fc-69d6-5bc3-ab81-b5a48df561bd"], "text": "— «Орбиту» я уже проверял. Свет там был и в пятницу, и в субботу. Справка у вас.", "grants": [], "supersedes": ["R11"]}, {"id": "R334", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Абишев читает журнал морга и морщится.\n— «Для хранения до выдачи родственникам». Красиво РОВД умеет не работать.\n(возвращает)\nЭто к Юрию Николаевичу, я в морг без нужды не спускаюсь. Там холодно, и он смеётся.", "grants": [], "fallback": true}, {"id": "R335", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "— Следы на снегу.\n(разводит руками)\nПо следам у меня картотеки нет. Если бы у ботинок был номер, как у машины, — пожалуйста. Это к Гуле.", "grants": [], "fallback": true}, {"id": "R336", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": [], "text": "Абишев листает фототаблицу РОВД.\n— Фотограф у них, видно, на один кадр плёнку экономил. Ну, так у нас.\n(откладывает)\nЗапросить тут нечего. Номеров нет.", "grants": [], "fallback": true}, {"id": "R337", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "— Копоть.\n(трёт пальцем по фотографии, будто она пачкает)\nКопоть в картотеку не положишь. Вывод сами. Мне бы номер, фамилию, хоть что-то.", "grants": [], "fallback": true}, {"id": "R338", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "Абишев смотрит на купюры, не трогая.\n— Пятьсот долларов. Моя зарплата за… а, неважно, за долго.\n(отодвигает)\nПо номерам купюр учёта у нас нет. Это к Гуле, у неё лупа лучше.", "grants": [], "fallback": true}, {"id": "R339", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "— Заметки следователя. Повязка, казан, плов.\n(пожимает плечами)\nПро ожоги учёта нет. Про травмпункты есть, но только если он туда ходил. А раз сам бинтовал — не ходил. Вывод сами.", "grants": [], "fallback": true}, {"id": "R340", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "Абишев с интересом листает журнал КПП.\n— Амбарная книга. Красота. Вот так бы все учёт вели, мне бы работы на полдня меньше.\n(возвращает)\nНо это уже готовые записи. Запрашивать по ним нечего, всё перед вами.", "grants": [], "fallback": true}, {"id": "R341", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": [], "text": "— Ксерокопии долларов. Ксерокс, наверное, на базе хороший, японский.\n(завистливо)\nУ нас один на всё управление, и тот с полосой. Номера сверять — это к Гуле.", "grants": [], "fallback": true}, {"id": "R342", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": [], "text": "Абишев вертит пейджер Нуртазина.\n— Номер абонента на наклейке есть. А запрос на что? Девочкам в пейджинговой основание нужно, просто так журнал не поднимут.\n(возвращает)\nБудет зацепка — подниму за день.", "grants": [], "fallback": true}, {"id": "R343", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "— Подвал, люк, лампа. Пальцы с люка изъяты, Гуля говорит.\n(вздыхает)\nРучное сравнение по всей картотеке — это до пенсии. Дайте фамилию — сравню с одной картой. С одной быстро.", "grants": [], "fallback": true}, {"id": "R344", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "— Шарф.\n(щупает край)\nХороший. В ЦУМе такой не купишь, только на барахолке у челночников. Но учёта на шарфы нет, извините. Вывод сами.", "grants": [], "fallback": true}, {"id": "R345", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "Абишев смотрит на бумажку под диском.\n— «48-27-15». Знакомый номер.\n(откладывает)\nЯ его уже поднимал. Чей — в справке. Больше по аппарату ничего не скажу.", "grants": [], "fallback": true}, {"id": "R346", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Вещи из общаги. Куртка с полосами, как у всех на Зелёном базаре.\n(отодвигает)\nПо одежде учёта нет. По деньгам — к Гуле. По человеку — дайте фамилию.", "grants": [], "fallback": true}, {"id": "R347", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": [], "text": "Абишев листает выписку из журнала вахты.\n— Вахтёрши — лучшая картотека в городе. Ни одна ЭВМ так не запомнит, кто во сколько пришёл.\n(возвращает)\nТут мне добавить нечего, всё уже записано.", "grants": [], "fallback": true}, {"id": "R348", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Ботинки.\n(не трогает)\nОбувь — это к Гуле. У меня ни одного ботинка в картотеке, только люди и машины.", "grants": [], "fallback": true}, {"id": "R349", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "Абишев читает расписку и присвистывает.\n— Купонный фонд. Помню, мать свои купоны туда же сдала. Где они теперь — никто не знает.\n(возвращает)\nПо фондам учёта у нас нет. Это налоговая. Вывод сами.", "grants": [], "fallback": true}, {"id": "R350", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Доллары в рисе.\n(качает головой)\nУ меня мама деньги в наволочку прячет. Тоже, видимо, по науке.\nПо номерам купюр — к Гуле.", "grants": [], "fallback": true}, {"id": "R351", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "— Моя справка, вторая половина. Девочки в пейджинговой журнал подняли.\n(с гордостью)\nДва раза ездил, они без печати не отдавали. Всё, что было, там. Вывод сами.", "grants": [], "fallback": true}, {"id": "R352", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "Абишев читает заключение Сеитовой.\n— Гуля посмотрела — значит, так и есть. Я в следах ничего не понимаю, а она понимает.\n(возвращает)\nЗапросить по этому нечего.", "grants": [], "fallback": true}, {"id": "R353", "on": "9eedb06d-09c9-5fa6-b91f-46d7753f78b4", "requires": [], "text": "— Моя справка. Электросети Кок-Тобе.\n(вздыхает)\nДиспетчер без печати не отдавал, пришлось ехать. Свет не горел с девятнадцати до двух. Это справка, не обвинение. Вывод сами.", "grants": [], "fallback": true}, {"id": "R354", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": [], "text": "— Моя справка, по «Орбите».\n(почти довольно)\nЗа пятницу и за субботу сразу, чтобы второй раз не ездить. Отключений не было. Это бумага, не приговор. Вывод сами.", "grants": [], "fallback": true}, {"id": "R355", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "Абишев узнаёт свою справку.\n— Адресное бюро. Очередь там была, как за колбасой в восемьдесят девятом.\n(возвращает)\nНомер на Шмидта, Шмидт в Германии. Всё, что было в учётах, там.", "grants": [], "fallback": true}, {"id": "R356", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "Абишев узнаёт свою справку.\n— Моя. Ручное сравнение: одну карту искал полдня, зато потом сверил быстро.\n(с гордостью)\nЭВМ, между прочим, так не умеет. Всё, что было в картотеке, там. Вывод сами.", "grants": [], "fallback": true}, {"id": "R357", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "— Моя выписка. Журнал оператора.\n(усмехается)\nДевочки в пейджинговой меня уже по голосу узнают. «ЧЕТВЕРГ В СИЛЕ? Ф.» — как написано, так и переписал. Вывод сами.", "grants": [], "fallback": true}, {"id": "R358", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": [], "text": "— Сравнение купюр. Это Гуля.\n(откладывает)\nЯ в купюрах разбираюсь как потребитель: их у меня мало. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R359", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": [], "text": "— Ботинки со следами совпали. Гуля подписала.\n(кивает)\nМне бы так всё совпадало в справках. Запрашивать по этому нечего.", "grants": [], "fallback": true}, {"id": "R360", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": [], "text": "— Опять доллары. Опять совпали.\n(устало)\nСкоро Гуля эти номера наизусть выучит. По моей части ничего.", "grants": [], "fallback": true}, {"id": "R361", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Абишев читает заключение Кана и чуть бледнеет.\n— Освидетельствование. Юрий Николаевич смотрел.\n(быстро возвращает)\nЭто не ко мне. Я про людей только на бумаге.", "grants": [], "fallback": true}, {"id": "R362", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "— Конверт из тех же денег. Гуля сверила.\n(тихо)\nНа похороны, значит.\n(пауза)\nПо моей части ничего. Вывод сами.", "grants": [], "fallback": true}, {"id": "R363", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "— Группы крови. Юрий Николаевич медкарты запрашивал.\n(с уважением)\nБез меня, сам. Старая школа. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R364", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "— Обувь всех проверили.\n(листает)\nГуля, видимо, неделю домой не ходила. По моей части запросить нечего.", "grants": [], "fallback": true}, {"id": "R365", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "Абишев узнаёт свою справку из ГАИ.\n— Моя. ИЦ и ГАИ, два окна, два дня.\n(перечисляет по пальцам)\nБелые — у двоих. Остальные — нет. Это справка, не обвинение. Вывод сами.", "grants": [], "fallback": true}, {"id": "R366", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Абишев читает санкцию.\n— Прокурор подписал. Быстро, кстати. Обычно неделю ходим.\n(возвращает)\nЗадержание — это опера. Мне запросить нечего.", "grants": [], "fallback": true}, {"id": "R367", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Моя справка. Учётное дело девяносто четвёртого, анкета, графа «родственники».\n(постукивает по листу)\nПотом адресное бюро, прописка по общагам. Три ящика перебрал. Что нашёл — то и написал. Вывод сами.", "grants": [], "fallback": true}, {"id": "R368", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "Абишев смотрит на сводную таблицу дат.\n— О, таблица. Это наука пришла.\n(усмехается)\nДаты в ней мои, из справок. Порядок — Аскар Бейсенович. По моей части всё сходится.", "grants": [], "fallback": true}]'::jsonb, fallback_lines = '{"testimony": ["— По этим показаниям запрос делать не по чему: ни номера, ни адреса, ни фамилии.", "— Слова в картотеку не положишь. Дайте номер — телефона, машины, дома — подниму.", "— Это показания, а мне нужна зацепка для запроса. Тут её нет. Вывод сами."], "expertise": ["— Это экспертиза, не справка. Запрос из неё делать не по чему.", "— Выводы — у экспертов. Мне дайте номер, адрес или фамилию."], "document": ["— Справка не моя, но бумага правильная. Запрашивать по ней больше нечего.", "— Бумагу видел. По моим учётам к ней добавить нечего."], "own_expertise": "— Это моя справка, не заключение. Что было в журналах — то и написал. Вывод сами.", "own_document": "— Это я вам и готовил. Всё, что было в учётах, там. Вывод сами.", "thing": ["— Номера на ней нет. Ни серийного, ни инвентарного. Без номера мне её запросить не по чему. Вывод сами.", "— Вещь как вещь. Мне бы бумажку с цифрами — я бы оживился."]}'::jsonb where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set name = 'Юрий Николаевич Кан', role = 'Судмедэксперт', intro_text = 'Юрий Николаевич Кан, судмедэксперт. Тридцать лет в морге. Нарукавники, очки на цепочке.
Кан моет руки. Не оборачивается.
— Давайте, что у вас. Только побыстрее: у меня их сегодня шестеро.', fixed_questions = '[{"q": "В гараже можно угореть?", "a": "— Можно. Каждую зиму привозят. Свет отключили, человек сел в машину погреться, а гараж закрыт. Ну вот. Только мне направление нужно. Без бумаги я вскрывать не буду."}, {"q": "Насколько надёжна группа крови как улика?", "a": "— Группа крови исключает, но не называет. Вторая — у каждого третьего в городе. Не совпала — значит, не он. Совпала — ищите дальше. Вот и всё.", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}]'::jsonb, reactions = '{"e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили уже мёртвым. Смерть — суббота, около двадцати двух. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это уже не ко мне.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — четверо-шестеро суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он в милиции служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — четверо-шестеро суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами.", "b177dd97-7391-5f5e-8308-72a1073516c2": "Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы."}'::jsonb, reaction_rules = '[{"id": "R01", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили уже мёртвым. Смерть — суббота, около двадцати двух. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это уже не ко мне.", "grants": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}, {"id": "R29", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — четверо-шестеро суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R49", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он в милиции служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет.", "grants": ["b177dd97-7391-5f5e-8308-72a1073516c2"]}, {"id": "R52", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — четверо-шестеро суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R53", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}, {"id": "R126", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Кан смотрит выписку поверх очков. Откладывает.\n— Угорел… Это РОВД так решил, голубчик. Без вскрытия ни я, ни они этого не знаем. Тело у меня в журнале с прочерком. Направьте — посмотрю.", "grants": [], "fallback": true}, {"id": "R127", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "— Видел я эту бумагу. Угара там нет, голубчик. Всё, что есть, в моём заключении.", "grants": [], "fallback": true}, {"id": "R128", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "Кан протирает очки полой халата.\n— Вторая группа. Под ногтями тоже вторая. Только поверьте старику: вторая группа у каждого третьего в городе. Группой можно исключить. Назвать человека группой нельзя.", "grants": [], "fallback": true}, {"id": "R129", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Раз задержан, приведите. Кровь возьму, руки посмотрю. Только сравнивать надо не на глаз, а с моей справкой по группам. Её и несите.", "grants": [], "fallback": true}, {"id": "R130", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Около десяти, голубчик. Плюс-минус час, точнее по трупу не скажу. А кто в это время курил на лестнице — это не ко мне.", "grants": [], "fallback": true}, {"id": "R131", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— Двадцать три двадцать, говорите… Смерть по моему заключению около двадцати двух. Через час его уже могли везти. Могли и не везти. Это я по трупу не определю.", "grants": [], "fallback": true}, {"id": "R132", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Наркоз в двадцать три десять? Это к анестезиологам, голубчик. Я скажу одно: умер он около десяти вечера. А где она была — это журналы, не морг.", "grants": [], "fallback": true}, {"id": "R133", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "Кан кивает.\n— С моим сходится. Щетина двое суток, обезвоживание. С четверга его где-то держали. Больше по пейджеру я вам не скажу.", "grants": [], "fallback": true}, {"id": "R134", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "— Сдавление шеи, тело в машину посадили мёртвым. С моим заключением сходится. Добавить нечего, голубчик.", "grants": [], "fallback": true}, {"id": "R135", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Через мешок узнал? По кашлю, по запаху — бывает, голубчик. Это не медицина, это память. Заключения тут я не дам.", "grants": [], "fallback": true}, {"id": "R209", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "— Это моё заключение, голубчик. Чьё там под ногтями — несите людей, кровь возьму.", "grants": [], "fallback": true}, {"id": "R210", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "— Моя таблица, голубчик. Группа исключает, не называет. Нового без задержанных не скажу.", "grants": [], "fallback": true}, {"id": "R246", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"], "text": "— Бекенова я смотрел, голубчик. Вторая группа, кисти чистые. В справке всё.", "grants": [], "supersedes": ["R129"], "fallback": true}, {"id": "R249", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Кан смотрит на пейджер поверх очков.\n— Мокрая машинка. Мне бы мокрого человека, голубчик, я бы рассказал, сколько он пролежал. А эта коробочка молчит не по моей части.", "grants": [], "fallback": true}, {"id": "R250", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "— Следы на снегу — это к Гульнаре. Она по подошве скажет больше, чем я по пятке живого человека.\n(возвращает листок)\nЯ ногу вижу, когда она уже на столе.", "grants": [], "fallback": true}, {"id": "R251", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": [], "text": "Кан листает фототаблицу РОВД, морщится.\n— Снимали, как на курорте: издалека и с выдержкой. Ну хоть сняли.\n(откладывает)\nТело я своё видел, голубчик. Снимки мне теперь ни к чему.", "grants": [], "fallback": true}, {"id": "R252", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "— Копоть на стене. Стена, голубчик, не дышит. Что угорел — не угорел, говорит кровь, а не побелка.\n(протирает очки)\nБелить я не умею.", "grants": [], "fallback": true}, {"id": "R253", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "— Телефон с цифрами. Внук у меня такие любит.\n(отодвигает)\nЭто к Ринату, голубчик. Наш бумажный бог по номерам кого угодно найдёт.", "grants": [], "fallback": true}, {"id": "R254", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "Кан не берёт конверт в руки.\n— Деньги не потеют и не синеют, голубчик. По ним я ничего не скажу. Скажу только, что на похороны обычно несут меньше.", "grants": [], "fallback": true}, {"id": "R255", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "Кан читает запись, хмыкает.\n— Казан, плов, ожог. Бывает, бывает. На моём веку от казана руки обжигали чаще, чем от пожара.\n(возвращает листок)\nСо слов я под бинт не загляну, голубчик. Мне нужна рука, а не рассказ про неё.", "grants": [], "fallback": true}, {"id": "R256", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Журнал проходной. Кто вошёл, кто вышел.\n(перелистывает, не читая)\nУ меня свой журнал, голубчик: кто вошёл и уже не вышел. Ваш — не по моей части.", "grants": [], "fallback": true}, {"id": "R257", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": [], "text": "Кан держит ксерокопию на вытянутой руке.\n— Восемь портретов на листе, и все одного человека. Это к Гульнаре, она купюры считает лучше кассира.", "grants": [], "fallback": true}, {"id": "R258", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": [], "text": "— Ещё один пейджер. Скоро у каждого сторожа будет.\n(вздыхает)\nВ наше время, голубчик, человека искали ногами. Это к Ринату.", "grants": [], "fallback": true}, {"id": "R259", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Кан читает протокол осмотра подвала. Долго. Снимает очки.\n— Матрас, ведро, верёвки. Двое суток, значит, там.\n(пауза)\nПро подвал — это Гульнара. А что он там пережил, я вам уже написал. Больше, чем написал, сказать не могу.", "grants": [], "fallback": true}, {"id": "R260", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "Кан берёт шарф, разворачивает край. Мягкий.\n— Хорошая вещь, тёплая. Под голову свернули, как подушку.\n(аккуратно складывает обратно)\nПо медицинской части в шерсти ничего, голубчик. Только сырость.", "grants": [], "fallback": true}, {"id": "R261", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "— Телефон в пустом доме. Гудок есть, а хозяев нет.\n(качает головой)\nЭто не ко мне. Я с аппаратами не разговариваю, голубчик, только с людьми, и то с молчаливыми.", "grants": [], "fallback": true}, {"id": "R262", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "Кан смотрит опись, не торопясь.\n— Куртка, шапка, ботинки, деньги за подкладкой. Молодой человек, судя по вещам.\n(откладывает)\nЖивых, голубчик, я не осматриваю, пока их ко мне не приведут. Это к Гульнаре.", "grants": [], "fallback": true}, {"id": "R263", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": [], "text": "— Журнал общежития. Вахтёрши, поверьте старику, точнее любого хронометра.\n(возвращает)\nНо время смерти я вам уже назвал. Остальное — ваша арифметика.", "grants": [], "fallback": true}, {"id": "R264", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Ботинки. Сорок третий.\n(не берёт)\nОбувь — это Гульнара. Я по ногам скажу, что человек долго стоял на холоде. По ботинкам — нет, голубчик.", "grants": [], "fallback": true}, {"id": "R265", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "Кан надевает очки, читает и тут же снимает.\n— Расписка. «Претензий не имею». Хорошая фраза. Мои пациенты тоже претензий не имеют.\n(возвращает)\nНе по моей части.", "grants": [], "fallback": true}, {"id": "R266", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Деньги в рисе. Рис в мешке.\n(усмехается)\nНа моём веку прятали в матрас и в банку с вареньем. Мода меняется, голубчик. Мне сказать нечего.", "grants": [], "fallback": true}, {"id": "R267", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "Кан читает заключение Сеитовой и кивает.\n— Гульнара — девочка точная. Если она пишет «ночные», значит ночные.\n(откладывает)\nСпорить не буду. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R268", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— Шофёр рассказывает про четверги.\n(протирает очки)\nПривычки, голубчик, — вещь опасная. Покойные их обычно не меняют. Но это к следователю, не ко мне.", "grants": [], "fallback": true}, {"id": "R269", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— «Месяц тебе, или сядешь». Громко сказано.\n(пожимает плечами)\nЯ слышу только тех, кто уже ничего не кричит, голубчик. Это к вам.", "grants": [], "fallback": true}, {"id": "R270", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Кан дочитывает показания Валентины Петровны. Долго молчит.\n— Мать. Платила и ждала у телефона.\n(возвращает лист аккуратно, двумя руками)\nПо моей части тут ничего. Тут не медицина, голубчик. Тут горе.", "grants": [], "fallback": true}, {"id": "R271", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— «Помирились». «Сидел при свечке».\n(откладывает)\nЯ людям на слово не верю, голубчик, и не потому, что злой. Просто у меня работа такая. Это к следователю.", "grants": [], "fallback": true}, {"id": "R272", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "Кан читает признание Ахметова. Хмурится.\n— Чёрная касса, курьер, остановка. Деньги, деньги.\n(возвращает)\nЭто не про тело, голубчик. Мне добавить нечего.", "grants": [], "fallback": true}, {"id": "R273", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "— «Иди завскладом». Обидные слова.\n(протирает очки)\nНа моём веку от обидных слов умирали реже, чем говорят. Но это уже не наука, голубчик, это психология. К Бейсенову.", "grants": [], "fallback": true}, {"id": "R274", "on": "9eedb06d-09c9-5fa6-b91f-46d7753f78b4", "requires": [], "text": "— Свет отключали. На Кок-Тобе это каждую неделю.\n(возвращает)\nТемнота, голубчик, на моём столе не видна. Видна асфиксия. Справка не по моей части.", "grants": [], "fallback": true}, {"id": "R275", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": [], "text": "Кан читает справку и пожимает плечами.\n— В «Орбите» свет был. Очень рад за «Орбиту».\n(отодвигает)\nЭто Ринат, голубчик. Он у нас по лампочкам.", "grants": [], "fallback": true}, {"id": "R276", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "— Немец, уехал в Германию, а телефон остался.\n(вздыхает)\nУезжают все, голубчик. Мне сказать нечего, это к адресному бюро.", "grants": [], "fallback": true}, {"id": "R277", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "— «Четверг в силе». Четыре слова.\n(возвращает бумагу)\nТелеграфный стиль. Я так в журнале пишу, когда некогда. По медицинской части ничего, голубчик.", "grants": [], "fallback": true}, {"id": "R278", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "Кан дочитывает признание Нуртазина.\n— Операция матери, полторы тысячи. Долг.\n(пауза)\nЗа долги, голубчик, люди делают странное. Медицина тут ни при чём. Это к вам.", "grants": [], "fallback": true}, {"id": "R279", "on": "3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0", "requires": [], "text": "Кан читает консультацию Бейсенова, чуть улыбается.\n— Аскар Бейсенович говорит «в типичном случае». Профили — это для живых, голубчик. У меня типичных случаев не бывает: каждый на своём столе.\n(возвращает)\nНо спорить не стану.", "grants": [], "fallback": true}, {"id": "R280", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": [], "text": "— Купюры совпали. Гульнара считала — значит, совпали.\n(откладывает)\nДеньги — не моё. Добавить нечего, голубчик.", "grants": [], "fallback": true}, {"id": "R281", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": [], "text": "— Ботинки совпали со следами. Гульнара подписала.\n(кивает)\nЕё подписи я верю, как своей. Медицины тут нет, голубчик.", "grants": [], "fallback": true}, {"id": "R282", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": [], "text": "Кан смотрит на протокол сравнения и отодвигает.\n— Опять доллары. Опять совпали.\n(устало)\nГолубчик, я по деньгам не эксперт. Гульнара — да.", "grants": [], "fallback": true}, {"id": "R283", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Кан узнаёт свой почерк на заключении.\n— Моё. Под повязкой — то, что написано, голубчик. Под каждой строкой подпишусь ещё раз.\n(возвращает)\nНовых материалов нет — нового не скажу.", "grants": [], "fallback": true}, {"id": "R284", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "— Конверт «на похороны» — из тех же денег.\n(долго смотрит, потом снимает очки)\nНа моём веку, голубчик, на похороны несли последнее. А тут несут чужое.\nПо медицинской части — ничего.", "grants": [], "fallback": true}, {"id": "R285", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "— Обувь всех проверили. Гульнара не поленилась.\n(возвращает)\nЯ бы так ноги не проверял, как она проверяет подошвы. Добавить нечего, голубчик.", "grants": [], "fallback": true}, {"id": "R286", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "— Машины, цвета, фары.\n(отодвигает справку)\nЯ, голубчик, тридцать лет на автобусе. В машинах не понимаю. Это к Ринату.", "grants": [], "fallback": true}, {"id": "R287", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Кан читает санкцию прокурора.\n— «Санкционирую». Фиолетовыми чернилами. Красиво пишут в прокуратуре.\n(возвращает)\nЗадерживать — это ваше. Приведёте — посмотрю. Таков порядок, голубчик.", "grants": [], "fallback": true}, {"id": "R288", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Племянник. Родня.\n(протирает очки)\nПо родне, голубчик, я только группы крови могу сравнить, и то если кровь дадут. А это бумага из адресного бюро. Не моё.", "grants": [], "fallback": true}, {"id": "R289", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "Кан находит в сводной справке свою строку.\n— Моя часть тут про руки. У обоих чистые, без царапин.\n(откладывает)\nЧистые руки, голубчик, — тоже результат. Иногда самый важный.", "grants": [], "fallback": true}, {"id": "R290", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "Кан смотрит на таблицу дат и разводит руками.\n— Девятое, четырнадцатое, шестнадцатое. Аскар Бейсенович любит таблицы.\n(возвращает)\nУ меня одна дата важна: когда остановилось сердце. Её я вам дал.", "grants": [], "fallback": true}, {"id": "R291", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— «Показывал дом покупателю». При керосиновой лампе.\n(качает головой)\nСказки, голубчик, рассказывают и живые, и мёртвые. Только мёртвые — по-честному. Это не ко мне.", "grants": [], "fallback": true}, {"id": "R292", "on": "3772cdd6-1fe9-52d0-a268-3f82441220c7", "requires": [], "text": "Кан читает справку об осмотре машины.\n— Глина в арках, руль без пальцев.\n(возвращает)\nМашину, голубчик, я не вскрываю. Это к Гульнаре.", "grants": [], "fallback": true}, {"id": "R293", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "Кан дочитывает показания Валентины Петровны. Снимает очки.\n— Рука, говорит, расцарапана. Собака на базаре.\n(пауза)\nСо слов, голубчик, я не освидетельствую. Мне нужна сама рука, на столе, при понятых. Порядок.", "grants": [], "fallback": true}]'::jsonb, fallback_lines = '{"testimony": ["— Со слов я заключений не даю, голубчик. Мне нужен материал: тело, кровь, рука.", "— Это к следователю. Моя наука начинается там, где есть что положить на стол."], "expertise": ["— Это не моё заключение, голубчик. Оспаривать не стану, добавить нечего.", "— Коллеги своё дело знают. По моей части тут ничего."], "document": ["— Бумага — это ваше, голубчик. По медицинской части в ней ничего.", "— Справка как справка. Тела в ней нет — и мне сказать нечего."], "own_expertise": "— Это моё заключение, голубчик. Новых материалов нет — нового не скажу.", "thing": ["— Вещь, голубчик, говорит, только когда на ней что-то есть: кровь, волос, след зубов. На этой — ничего моего.", "— Поверьте старику: я смотрю на то, что вещь сделала с человеком. Эта, похоже, ничего не сделала. Не по моей части."]}'::jsonb where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set name = 'Аскар Бейсенов', role = 'Криминолог, доцент высшей школы МВД', intro_text = 'Аскар Бейсенов, криминолог, доцент Высшей школы МВД. Пиджак, кожаный портфель, отточенный карандаш.
Бейсенов постукивает карандашом по блокноту.
— Давайте с фактов. Предположения потом.', fixed_questions = '[{"q": "Чем вы можете помочь?", "a": "— Типологией. Я могу сказать, как обычно ведут себя люди в такой ситуации и кто в неё, как правило, попадает. А кто попал в вашу — это уже следствие. Не наука."}, {"q": "Почему семья молчала?", "a": "— К сожалению, это типично. Милиции у нас не доверяют, и давно. Семья боится не столько похитителей, сколько того, что милиция их спугнёт. И учтите: молчание свидетеля — ещё не соучастие.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}]'::jsonb, reactions = '{"34e1077a-bcc2-53ac-90e8-702d023d03c7": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше.", "0a295d5f-e115-5c89-a26a-5992761304a0": "Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой стоит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, потом план. Имён я не называю. Это порядок дат."}'::jsonb, reaction_rules = '[{"id": "R23", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше.", "grants": ["3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0"]}, {"id": "R56", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf"], "text": "Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой стоит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, потом план. Имён я не называю. Это порядок дат.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}, {"id": "R165", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Бейсенов постукивает карандашом по выписке.\n— Протокол фиксирует версию, а не факт. Пока нет вскрытия, профиль строить не по чему.", "grants": [], "fallback": true}, {"id": "R166", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "— Удушение, связывание, двое суток. Позвольте не спешить. Мне нужно понять, что происходило эти двое суток. Требовали что-нибудь у семьи?", "grants": [], "fallback": true}, {"id": "R167", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "— Похищение с выкупом. Выкуп получен, заложник мёртв. Как правило, это многое говорит. Но мне нужна картина места: как и в каком виде его оставили в гараже.", "grants": [], "fallback": true}, {"id": "R168", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Мотив налицо. Но мотив без дат — половина картины. Когда начали готовить — вот что важно. Сложите даты.", "grants": [], "fallback": true}, {"id": "R169", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "— Позвольте: здесь есть дата начала подготовки. Это ценно. Но одна дата — не хронология. Нужны другие, с ними и сравним.", "grants": [], "fallback": true}, {"id": "R170", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— Регулярность — первое, что изучает похититель. Кто знал расписание — вопрос к вам, не ко мне. Я говорю категориями.", "grants": [], "fallback": true}, {"id": "R171", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— «Я сам всё придумал». Позвольте сформулировать: это фраза, которую проверяют, а не принимают. Проверять — фактами. Профиль здесь не поможет.", "grants": [], "fallback": true}, {"id": "R172", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Это уже показания против конкретного лица. Здесь моя работа закончена. Имён я не называю.", "grants": [], "fallback": true}, {"id": "R173", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": ["3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0"], "text": "— В типичном случае так и бывает: убивают, когда боятся опознания. Это я вам говорил. Остальное — дело следствия.", "grants": [], "fallback": true}, {"id": "R369", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Бейсенов читает журнал морга. Постукивает карандашом по прочерку.\n— Позвольте заметить: это не ошибка, это система. Районы экономят на экспертизе, когда версия удобна.\n(возвращает)\nНо это наблюдение о РОВД, не о деле. По существу — к Юрию Николаевичу.", "grants": [], "fallback": true}, {"id": "R370", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "— Пейджер в арыке.\n(вертит в руках, кладёт)\nПредмет сам по себе немой. Интересно не что это, а кто и почему его здесь оставил. Но без фактов я гадать не стану.", "grants": [], "fallback": true}, {"id": "R371", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Бейсенов смотрит схему следов.\n— Следы — это к Гульнаре Маратовне.\n(пауза)\nПросто Сеитова, да, она меня всегда поправляет. Скажет она — тогда я скажу, что это значит.", "grants": [], "fallback": true}, {"id": "R372", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": [], "text": "Бейсенов долго смотрит на борозды и фототаблицу.\n— Деталь. Деталь без системы — шум.\n(постукивает карандашом)\nДайте мне сначала заключение судмедэксперта. Тогда поговорим, что это за люди.", "grants": [], "fallback": true}, {"id": "R373", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "— Копоть.\n(откладывает снимок)\nВ типичном случае несчастный случай выглядит именно так. Это и настораживает, но не доказывает. Позвольте не спешить.", "grants": [], "fallback": true}, {"id": "R374", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "Бейсенов разглядывает определитель номера.\n— Удивительная вещь, прогресс. Пять лет назад такого не было ни у кого.\n(кладёт)\nНомера — это к вашему оператору. Мне нужны не номера, а люди за ними.", "grants": [], "fallback": true}, {"id": "R375", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Конверт. «На похороны».\n(не прикасается)\nС точки зрения криминологии, деньги на похороны — жест. Жесты бывают искренние и показные. Какой этот — я по конверту не скажу.", "grants": [], "fallback": true}, {"id": "R376", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "Бейсенов дочитывает заметку о повязке.\n— Травма, объяснение, бытовая версия.\n(постукивает)\nЛюди объясняют травмы постоянно, и, как правило, честно. Одна деталь — не основание. Позвольте воздержаться.", "grants": [], "fallback": true}, {"id": "R377", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "Бейсенов листает журнал КПП, увлечённо.\n— Вот это материал. Сотни записей, ритм жизни предприятия. Кто приходит, когда, к кому.\n(закрывает, с сожалением)\nНо читать его должен следователь. Я скажу, что значит закономерность, когда вы её найдёте.", "grants": [], "fallback": true}, {"id": "R378", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": [], "text": "— Ксерокопии купюр.\n(с уважением)\nКто-то в этой истории мыслит как бухгалтер: снял копии на всякий случай. Это говорит о недоверии. К кому — уже ваш вопрос.", "grants": [], "fallback": true}, {"id": "R379", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": [], "text": "— Пейджер охранника.\n(кладёт)\nОхрана, как правило, знает о привычках хозяев больше, чем семья. Это общее наблюдение. По этому предмету — ничего конкретного.", "grants": [], "fallback": true}, {"id": "R380", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Бейсенов читает протокол осмотра подвала. Медленно. Снимает очки.\n— Матрас, ведро, верёвки. Двое суток.\n(пауза)\nВ моей практике такие места выбирали не случайно: тихо, пусто, знакомо. Но знакомо кому — это из протокола не следует.", "grants": [], "fallback": true}, {"id": "R381", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "Бейсенов разглядывает шарф.\n— Дорогая вещь в грязном подвале. Под головой.\n(постукивает карандашом)\nЛибо забота, либо небрежность. Я бы не спешил выбирать.", "grants": [], "fallback": true}, {"id": "R382", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "— Телефон в пустом доме.\n(задумчиво)\nПустые дома — классика. Хозяева далеко, соседи привыкли не смотреть. Для профиля это пока только декорация.", "grants": [], "fallback": true}, {"id": "R383", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Вещи молодого человека. Деньги за подкладкой.\n(откладывает опись)\nТак прячет тот, кому прятать больше негде. Больше по одной описи я не скажу.", "grants": [], "fallback": true}, {"id": "R384", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": [], "text": "— Журнал вахты.\n(кладёт)\nВахтёрши, как правило, надёжнее камер, которых у нас всё равно нет. Это фиксация присутствия. Что из неё следует — решайте по совокупности.", "grants": [], "fallback": true}, {"id": "R385", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Ботинки.\n(не берёт)\nОбувь — это уже предметное доказательство. Не моя область. Сопоставление проведёт криминалист.", "grants": [], "fallback": true}, {"id": "R386", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "Бейсенов читает расписку, хмурится.\n— Купонный инвестиционный фонд. Позвольте отступление: эти фонды — отдельная тема для диссертации. Через них за два года передали из рук в руки полстраны.\n(откладывает)\nК вашему делу это, вероятно, имеет косвенное отношение. Пока — только косвенное.", "grants": [], "fallback": true}, {"id": "R387", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Тайник в рисе.\n(почти с улыбкой)\nБытовая изобретательность. Прятать в продуктах — привычка людей, которые помнят дефицит.\n(серьёзно)\nСамо по себе это ни о чём не говорит. Сопоставление — за криминалистом.", "grants": [], "fallback": true}, {"id": "R388", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "— Пейджер молчал с четверга.\n(записывает)\nПризнак того, что человек исчез внезапно. Фиксирую. На профиль влияет только вместе с остальным.", "grants": [], "fallback": true}, {"id": "R389", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "Бейсенов читает заключение Сеитовой.\n— Женские следы днём, мужские ночью. Два разных эпизода.\n(постукивает)\nЭто хорошо: время разделяет людей. Но кто есть кто — пока не моя часть.", "grants": [], "fallback": true}, {"id": "R390", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Бывшая жена была на даче днём.\n(откладывает)\nБывшие супруги — классический круг подозрения. Именно поэтому, как правило, их проверяют первыми и именно поэтому ошибаются чаще всего. Решайте по фактам.", "grants": [], "fallback": true}, {"id": "R391", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— «Давно помирились». «Сидел при свечке».\n(внимательно перечитывает)\nЛюди, которые приходят с соболезнованиями, обычно говорят лишнее. Иногда — от горя. Иногда — нет. По этим словам различить нельзя.", "grants": [], "fallback": true}, {"id": "R392", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "Бейсенов дочитывает признание Ахметова.\n— Чёрная касса, страх, молчание по просьбе семьи.\n(пауза)\nСледует отличать вину перед законом от вины в преступлении. Это разные вещи. Профиль от этого не меняется.", "grants": [], "fallback": true}, {"id": "R393", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "— Отказ в доле. Публичное унижение.\n(медленно)\nУнижение — сильный мотив, это известно. Но мотив есть у многих, а действие совершают единицы. Позвольте не делать выводов из одной сцены.", "grants": [], "fallback": true}, {"id": "R394", "on": "9eedb06d-09c9-5fa6-b91f-46d7753f78b4", "requires": [], "text": "— Свет отключали.\n(записывает в блокнот)\nВажно, кто об этом знал заранее. Но справка этого не говорит. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R395", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": [], "text": "— Справка по «Орбите».\n(откладывает)\nЭто проверка чьих-то слов. Слова либо подтверждаются, либо нет. Профилю такие справки помогают меньше, чем следствию.", "grants": [], "fallback": true}, {"id": "R396", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "— Телефон эмигранта.\n(задумчиво)\nНемцы уезжают, дома пустеют. Социальное явление, между прочим, я об этом статью писал.\n(спохватывается)\nК делу: пустой дом как место — показателен. Кто его знал — ваш вопрос.", "grants": [], "fallback": true}, {"id": "R397", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "Бейсенов читает справку по пальцам.\n— Совпадение следов пальцев — это присутствие, не действие.\n(постукивает)\nЧеловек мог там быть по многим причинам. Криминология начинается, когда присутствие складывается с мотивом и временем.", "grants": [], "fallback": true}, {"id": "R398", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— Соседка видела машину.\n(записывает)\nПоказания соседей, как правило, точны во времени и неточны в людях. Учтите это. Остальное — за следствием.", "grants": [], "fallback": true}, {"id": "R399", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "— «ЧЕТВЕРГ В СИЛЕ? Ф.».\n(перечитывает)\nТелеграфный стиль, подпись одной буквой. Так пишут люди, которые договорились заранее. Кто такой «Ф.» — уже не мой вопрос.", "grants": [], "fallback": true}, {"id": "R400", "on": "3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0", "requires": [], "text": "Бейсенов узнаёт свою консультацию и чуть выпрямляется.\n— Моя. Я стою на каждом слове.\n(постукивает карандашом по выводу)\nБез новых данных менять её не буду. Позвольте только напомнить: это профиль, а не обвинение.", "grants": [], "fallback": true}, {"id": "R401", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": [], "text": "— Деньги выкупа нашлись.\n(кивает)\nЭто факт. Как и почему они туда попали — вопрос следствия, а не профиля.", "grants": [], "fallback": true}, {"id": "R402", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": [], "text": "— Обувь совпала со следами.\n(откладывает)\nЭто уже не криминология, это криминалистика. Факт сильный. Мне добавить нечего.", "grants": [], "fallback": true}, {"id": "R403", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": [], "text": "— Деньги из тайника — выкупные.\n(пауза)\nФакт. Объяснять факты — не моя роль. Моя роль — объяснять людей.", "grants": [], "fallback": true}, {"id": "R404", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Бейсенов читает заключение Кана.\n— Юрий Николаевич, старая школа. Если он написал «ногти», значит ногти.\n(возвращает)\nМедицинские выводы я не комментирую.", "grants": [], "fallback": true}, {"id": "R405", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "— Конверт «на похороны» — из выкупных денег.\n(долго молчит, потом тихо)\nВ моей практике такое встречалось. Редко. Это говорит о человеке больше, чем любая экспертиза.\n(серьёзно)\nНо выводы — ваши.", "grants": [], "fallback": true}, {"id": "R406", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "— Группы крови.\n(раскладывает)\nОтсев по группе — инструмент грубый, но честный. Двоих не исключает, двоих исключает. Дальше — по совокупности.", "grants": [], "fallback": true}, {"id": "R407", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "— Обувь остальных не совпала.\n(кивает)\nОтсев проведён. Методически правильно. Мне комментировать нечего.", "grants": [], "fallback": true}, {"id": "R408", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "— Машины по цвету.\n(записывает)\nЕщё один грубый, но честный фильтр. Позвольте похвалить: вы работаете системно.", "grants": [], "fallback": true}, {"id": "R409", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Бейсенов читает санкцию прокурора.\n— Процессуальное решение. Не моя компетенция.\n(возвращает)\nЕсли позволите совет: на допросе дайте человеку говорить. Молчание иногда показательнее слов.", "grants": [], "fallback": true}, {"id": "R410", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Родственник. Племянник.\n(постукивает)\nРодство в уголовных делах встречается часто — и как связь, и как простое совпадение. По одной анкете не скажу, что здесь.", "grants": [], "fallback": true}, {"id": "R411", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Сводная справка по экспертизам.\n(читает внимательно)\nОтсев. Это хорошая работа ваших коллег. Профиль от этого становится уже. Мне добавить нечего.", "grants": [], "fallback": true}, {"id": "R412", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Соседка видела машину до ночи.\n(откладывает)\nАлиби, подтверждённое случайным свидетелем, как правило, надёжнее алиби от близких. Это общее правило.", "grants": [], "fallback": true}, {"id": "R413", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "Бейсенов узнаёт свою таблицу.\n— Хронология. Моя любимая форма.\n(с удовольствием проводит карандашом по датам)\nДаты не лгут, лгут люди. Таблица перед вами. Без новых дат менять её не буду.", "grants": [], "fallback": true}, {"id": "R414", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— «Показывал дом покупателю».\n(чуть усмехается)\nВторая версия после того, как первая не выдержала проверки. Это типично. Но типичное — не доказательство. Проверяйте.", "grants": [], "fallback": true}, {"id": "R415", "on": "3772cdd6-1fe9-52d0-a268-3f82441220c7", "requires": [], "text": "— Машина: глина, чистый руль.\n(записывает)\nЧистый руль — это интересно с точки зрения поведения. Но интерпретировать криминалистические данные должен криминалист.", "grants": [], "fallback": true}, {"id": "R416", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "Бейсенов читает показания Валентины Петровны.\n— «Береги Дашу».\n(долго молчит)\nЗабота и угроза в одной фразе. В типичном случае их невозможно различить по словам. Только по поступкам.", "grants": [], "fallback": true}]'::jsonb, fallback_lines = '{"testimony": ["— Позвольте: одни показания — это эпизод. Для профиля нужна картина: что, когда, в каком порядке.", "— В типичном случае такие слова профиль не меняют. Добавить нечего.", "— Это сведения о конкретном лице. Я говорю категориями, не именами."], "expertise": ["— Выводы коллег принимаю. На профиль, как правило, они не влияют.", "— Это факт, а не закономерность. От себя добавить нечего."], "document": ["— Справка фиксирует факт. Для профиля этого мало.", "— Документ как документ. Закономерности в нём нет."], "own_expertise": "— Это моя консультация. Без новых данных я её не меняю.", "thing": ["— Предмет сам по себе немой. Интересно, кто и зачем его так положил. Без контекста — воздержусь.", "— Это материальное доказательство, позвольте, не моя область. Я работаю с поведением, а не с вещами."]}'::jsonb where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
commit;
select name, jsonb_array_length(reaction_rules) as rules from characters where name in ('Юрий Николаевич Кан','Гульнара Сеитова','Ринат Абишев','Аскар Бейсенов') and case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';
